$ErrorActionPreference = "Continue"
Set-Location C:\Users\Administrator\Documents\ChatGPT\Hackathons\LEGION-Commerce-Q002
$py = ".\.venv\Scripts\python.exe"; $E = "latency004\evidence\final"
New-Item -ItemType Directory -Force $E | Out-Null
function Quiet { Start-Sleep 45; while (Get-Process lake,lean -ErrorAction SilentlyContinue) { "waiting: foreign lake/lean build active $(Get-Date -Format o)"; Start-Sleep 30 } }
"START $(git rev-parse HEAD) $(Get-Date -Format o)"
Quiet; & $py -B latency004\bench.py "$E\bench_dedicated_BCh_b2b" 2000 10 "BCh" "repeat,fresh" *> "$E\bench_dedicated_BCh_b2b.log"; "1 exit $LASTEXITCODE $(Get-Date -Format o)"
Quiet; $env:PACE_MS = "20"; & $py -B latency004\bench.py "$E\bench_dedicated_BCh_paced20" 2000 10 "BCh" "repeat,fresh" *> "$E\bench_dedicated_BCh_paced20.log"; "2 exit $LASTEXITCODE"
Quiet; & $py -B latency004\bench.py "$E\bench_dedicated_BC_paced20" 2000 10 "BC" "repeat,fresh" *> "$E\bench_dedicated_BC_paced20.log"; "3 exit $LASTEXITCODE"
Quiet; & $py -B latency004\bench.py "$E\bench_dedicated_A_paced20" 1000 10 "A" "repeat,fresh" *> "$E\bench_dedicated_A_paced20.log"; Remove-Item Env:PACE_MS; "4 exit $LASTEXITCODE"
Quiet; & $py -B latency004\bench.py "$E\bench_dedicated_A_b2b" 1000 10 "A" "repeat,fresh" *> "$E\bench_dedicated_A_b2b.log"; "5 exit $LASTEXITCODE"
Quiet; & $py -B latency004\bench.py "$E\bench_interleaved_b2b" 1000 10 "A,B,C,BC" "repeat,fresh,fresh_cold" *> "$E\bench_interleaved_b2b.log"; "6 exit $LASTEXITCODE $(Get-Date -Format o)"
foreach ($a in "A","B","C","BC","BCh") { Quiet; & $py -B latency004\profile_arch.py "$E\wp2_profiles" $a repeat 1000 100 *> "$E\wp2_profile_$a.log"; "profile $a exit $LASTEXITCODE" }
Quiet; & $py -B latency004\profile_arch.py "$E\wp2_profiles" BCh fresh 1000 100 *> "$E\wp2_profile_BCh_fresh.log"; "profile BCh fresh exit $LASTEXITCODE"
Quiet; & $py -B latency004\profile_paced.py "$E\wp1_paced_profiles" BC 20 1000 100 *> "$E\wp1_profile_paced_BC.log"; "paced BC exit $LASTEXITCODE"
Quiet; & $py -B latency004\profile_paced.py "$E\wp1_paced_profiles" BCh 20 1000 100 *> "$E\wp1_profile_paced_BCh.log"; "paced BCh exit $LASTEXITCODE"
Quiet; & $py -B latency004\exp_overlap.py "$E\E6_OVERLAP.json" 10 100 *> "$E\E6_overlap.log"; "E6 exit $LASTEXITCODE"
Quiet; & $py -B latency004\exp_worker_glue.py "$E\E2b_WORKER_GLUE.json" *> "$E\E2b_worker_glue.log"; "E2b exit $LASTEXITCODE"
Quiet; & $py -B latency004\exp_qos.py "$E\E1e_QOS.json" 20 8 150 *> "$E\E1e_qos.log"; "E1e exit $LASTEXITCODE"
Quiet; & $py -B latency004\exp_idle.py "$E\E1f_IDLE.json" 20 8 150 *> "$E\E1f_idle.log"; "E1f exit $LASTEXITCODE"
Quiet; & $py -B latency004\exp_ecoqos.py "$E\E1b_ECOQOS.json" 6 *> "$E\E1b_ecoqos.log"; "E1b exit $LASTEXITCODE"
Quiet; & $py -B latency004\exp_file_open.py "$E\E1c_FILE_FIRST_OPEN.json" *> "$E\E1c_file_open.log"; "E1c exit $LASTEXITCODE"
"TIMING DONE $(Get-Date -Format o)"
& $py -B tools\qualify_commerce.py --arch BCh *> "$E\wp4_qualify_BCh.log"; "qualify exit $LASTEXITCODE"
& $py -B latency004\robustness.py "$E\wp4_robustness" 8 150 BCh *> "$E\wp4_robustness.log"; "robustness exit $LASTEXITCODE"
& $py -B latency004\test_clock_skew.py "$E\WP4_CLOCK_SKEW.json" BCh *> "$E\wp4_clock_skew.log"; "clockskew exit $LASTEXITCODE"
& $py -B latency004\equivalence.py "$E\wp4_equivalence_run" 40 "A,B,C,BC,BCh" *> "$E\wp4_equivalence_run.log"; "equivalence exit $LASTEXITCODE $(Get-Date -Format o)"
& $py -B latency004\equivalence.py "$E\wp4_equivalence_replay" 40 "A,BCh" *> "$E\wp4_equivalence_replay.log"; "replay exit $LASTEXITCODE"
"DONE $(Get-Date -Format o)"
